def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    yesterday_bids = []
    desperate_opp = 0
    rich_opp = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opp += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    yesterday_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    high_supply = supply >= 22
    low_supply = supply <= 17

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if day >= 8:
        urgency += 1

    if low_supply:
        urgency += 1
    elif high_supply:
        urgency -= 1

    base = 0.0

    if urgency >= 5:
        base = 0.96 * DAILY_SALARY
    elif urgency >= 3:
        if highest_prev >= 100:
            base = min(0.92 * DAILY_SALARY, highest_prev + 2.0)
        else:
            base = max(0.78 * DAILY_SALARY, highest_prev + 1.5)
    else:
        if high_supply:
            base = 0.24 * DAILY_SALARY
        elif low_supply:
            base = 0.48 * DAILY_SALARY
        else:
            base = 0.34 * DAILY_SALARY

        if highest_prev >= 110:
            base = min(base, 0.28 * DAILY_SALARY)
        elif highest_prev >= 85:
            base = max(base, 0.52 * DAILY_SALARY)
        elif highest_prev >= 50:
            base = max(base, min(highest_prev + 1.25, 0.7 * DAILY_SALARY))

    if desperate_opp >= 2 and urgency <= 2:
        base *= 0.9
    if rich_opp >= 2 and low_supply and urgency >= 3:
        base *= 1.08

    reserve_days = max(1, 11 - day)
    soft_cap = budget / reserve_days + DAILY_SALARY * 0.15
    if urgency <= 2:
        base = min(base, soft_cap)

    if hp <= 2 or no_water >= 2:
        hard_floor = 0.82 * DAILY_SALARY
        base = max(base, hard_floor)

    bid = min(budget, max(0.0, base))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Examine only yesterday's immediate behavior via previous_trace
    prev_bids = []
    for o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        bid = pt.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_highest = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_highest = float(sorted_b[1])

    # Estimate how many water units we can reasonably expect to need
    # If supply is low, competition is harsher; if our hp/no_water is low, bid more.
    # Baseline: aim moderate to avoid overpaying like Alex/Cindy.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_ratio < 0.0:
            supply_ratio = 0.0
        if supply_ratio > 1.0:
            supply_ratio = 1.0

    # Pressure factor from yesterday's bids (if others overbid heavily, we can undercut)
    # Alex/Cindy died with very high bids; if highest_prev_bid is extreme, reduce.
    extreme_threshold = 150.0
    high_threshold = 120.0

    if highest_prev_bid >= extreme_threshold:
        pressure = 0.25
    elif highest_prev_bid >= high_threshold:
        pressure = 0.45
    else:
        pressure = 0.60

    # Need factor from our status
    if my_hp <= 1:
        need = 1.0
    elif my_hp <= 3:
        need = 0.85
    elif my_no_water_days >= 3:
        need = 0.75
    else:
        need = 0.55

    # Compute target bid fraction of DAILY_SALARY
    # When pressure is high (others bidding hard), we still don't want to mirror their extreme behavior.
    target_fraction = (pressure * 0.55 + need * 0.45)

    # Add small bump if supply is low
    if supply <= float(WATER_REQ):
        target_fraction += 0.10
    else:
        target_fraction += 0.05 * (1.0 - supply_ratio)

    # Clamp to sensible range
    if target_fraction < 0.25:
        target_fraction = 0.25
    if target_fraction > 0.95:
        target_fraction = 0.95

    # Strategy: if yesterday's top bids were extreme, undercut slightly below second-highest pressure.
    bid = DAILY_SALARY * target_fraction

    # If we have enough budget, and there was a strong (but not extreme) competitor, bid just above their typical level.
    # Use previous_trace bid as a guide, but keep within budget.
    if highest_prev_bid >= high_threshold and second_highest > 0.0:
        # Undercut by a small amount to win without matching extremes.
        bid = min(bid, second_highest + 5.0)

    # If we're in danger, allow higher bid.
    if my_hp <= 2 or my_no_water_days >= 4:
        bid = max(bid, DAILY_SALARY * 0.75)

    # Final cap by budget
    if my_budget <= 0.0:
        return 0.0

    if bid > my_budget:
        bid = my_budget

    # Ensure bid is non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # 1. If no opponents, bid minimally
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # 2. Determine base bid based on my status
    base_bid = DAILY_SALARY * 0.8 # Start with a competitive base

    if my_status['no_water_days'] == 1:
        base_bid = DAILY_SALARY * 1.0
    elif my_status['no_water_days'] >= 2:
        base_bid = DAILY_SALARY * 1.3

    # Late game desperation boost if HP is low
    if my_status['hp'] <= 3 and day_context['day'] > EPISODE_DAYS / 2:
        base_bid = max(base_bid, DAILY_SALARY * 1.5)

    # 3. Adjust for opponent's previous bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If highest opponent bid was higher than my current base, bid slightly above it
        if highest_prev_bid > base_bid:
            base_bid = highest_prev_bid + 2.0 # Bid just a little higher

    # Ensure a minimum competitive bid if it became too low
    base_bid = max(base_bid, DAILY_SALARY * 0.5)

    # 4. Adjust for supply scarcity
    num_slots = int(day_context['supply'] / WATER_REQ)
    num_competitors = len(alive_opponents) + 1 # Including myself

    if num_slots == 0: # Extremely scarce, no one can get full water
        scarcity_multiplier = 2.0 # Bid very high to try to get some water
    elif num_competitors > num_slots:
        # Higher competition means higher bids
        scarcity_multiplier = 1.0 + (num_competitors - num_slots) * 0.2
    else:
        scarcity_multiplier = 1.0 # Enough water for everyone, no extra pressure

    base_bid *= scarcity_multiplier

    # 5. Final bid, limited by budget
    return min(my_status['budget'], base_bid)

